const floorImage = "/manus-storage/forge-bodyweight-floor_b538a0da.jpg";
const nutritionImage = "/manus-storage/forge-nutrition_47886e8b.jpg";
const movementUrl = (duration = 20, focus = "Strength", level = "Beginner") => `/workout/${duration}-${focus.toLowerCase().replace(/\s+/g, "-")}-${level.toLowerCase()}?duration=${duration}&focus=${encodeURIComponent(focus)}&level=${level}`;
function ReferenceMedia({ src, alt }: { src: string; alt: string }) {
  return /\.(mp4|webm)(?:\?.*)?$/i.test(src) ? <video src={src} controls playsInline preload="metadata" aria-label={alt} /> : <img src={src} alt={alt} loading="eager" decoding="async" />;
}

export function ProtectedPage({ children, admin = false }: { children: React.ReactNode; admin?: boolean }) {
  const { user, loading } = useAuth();
  const [, setLocation] = useLocation();
  useEffect(() => {
    if (loading) return;
    if (!user) {
      const returnTo = window.location.pathname + window.location.search;
      window.sessionStorage.setItem("forge.returnAfterAuth", returnTo);
      setLocation(admin ? "/admin/login" : `/login?returnTo=${encodeURIComponent(returnTo)}`);
    } else if (admin && user.role !== "admin") setLocation("/admin/login");
  }, [user, loading, admin, setLocation]);
  if (loading || !user || (admin && user.role !== "admin")) return <div className="page-loader"><span className="loader-line" /><p>Checking your FORGE access…</p></div>;
  return <>{children}</>;
}

